=== FILE: tb_crc8.v ===
// Self-checking constrained-random testbench for crc8_block.
// Reference model and expected values are written from interface_spec.md
// (crc8_block), not from the RTL. Inputs are driven on the falling edge;
// outputs are sampled 1 ns after the rising edge.
`timescale 1ns / 1ps
module tb_crc8;
    reg        clk   = 1'b0;
    reg        rst_n = 1'b0;
    reg        init  = 1'b0;
    reg        valid = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire [7:0] crc;

    crc8_block dut (
        .clk  (clk),
        .rst_n(rst_n),
        .init (init),
        .valid(valid),
        .data (data),
        .crc  (crc)
    );

    always #5 clk = ~clk;

    // ------------------------------------------------------------------
    // Run bookkeeping
    // ------------------------------------------------------------------
    localparam integer SEED = 32'h5EEDC8C8;
    integer seed;
    integer n_pass = 0;
    integer n_fail = 0;
    reg [8*256-1:0] nonce;
    reg             have_nonce;

    // Reference model state (spec 2: 8-bit running value, start 0xFF)
    reg [7:0] m_run   = 8'hFF;
    reg       m_known = 1'b0;
    integer   frame_len = 0;

    // Coverage / corner counters
    integer c_bytes       = 0;
    integer c_hold        = 0;
    integer c_init_valid  = 0;
    integer c_init_mid    = 0;
    integer c_rst_valid   = 0;
    integer c_rst_init    = 0;
    integer c_rst_mid     = 0;
    integer c_long        = 0;
    integer c_corner_data = 0;
    integer c_empty       = 0;

    // ------------------------------------------------------------------
    // Spec 2.2 model, written as: XOR the whole byte into the running
    // value, then 8 shift steps, each XORing 0x07 when a 1 leaves bit 7.
    // (Equivalent to the per-bit description for an MSB-first,
    // non-reflected CRC.)
    // ------------------------------------------------------------------
    function [7:0] spec_take_byte(input [7:0] run, input [7:0] b);
        reg [8:0] w;
        integer k;
        begin
            w = {1'b0, run ^ b};
            for (k = 0; k < 8; k = k + 1) begin
                w = {w[7:0], 1'b0};
                if (w[8])
                    w[7:0] = w[7:0] ^ 8'h07;
            end
            spec_take_byte = w[7:0];
        end
    endfunction

    // ------------------------------------------------------------------
    // Checking
    // ------------------------------------------------------------------
    task check(input [8*48-1:0] what, input [7:0] exp);
        begin
            if (crc !== exp) begin
                n_fail = n_fail + 1;
                if (n_fail <= 20)
                    $display("MISMATCH t=%0t %0s: crc=%h expected=%h (rst_n=%b init=%b valid=%b data=%h frame_len=%0d)",
                             $time, what, crc, exp, rst_n, init, valid, data, frame_len);
            end else begin
                n_pass = n_pass + 1;
            end
        end
    endtask

    task require_count(input [8*48-1:0] what, input integer got, input integer min);
        begin
            if (got < min) begin
                n_fail = n_fail + 1;
                $display("COVERAGE HOLE %0s: reached %0d, need >= %0d", what, got, min);
            end else begin
                n_pass = n_pass + 1;
                $display("coverage %0s: %0d (>= %0d)", what, got, min);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // One clock cycle: drive at negedge, model at posedge, compare after.
    // ------------------------------------------------------------------
    task step(input r, input i, input v, input [7:0] d);
        reg reloaded;
        begin
            reloaded = 1'b0;
            @(negedge clk);
            rst_n = r;
            init  = i;
            valid = v;
            data  = d;
            #1;
            // CRC-FINAL: crc follows the running value only; changing the
            // inputs without a clock edge must not move it.
            if (m_known) check("CRC-FINAL no change without edge", m_run ^ 8'hFF);

            @(posedge clk);
            if (!r) begin
                // CRC-RESET
                if (v) c_rst_valid = c_rst_valid + 1;
                if (i) c_rst_init  = c_rst_init + 1;
                if (m_known && frame_len > 0) c_rst_mid = c_rst_mid + 1;
                m_run = 8'hFF; m_known = 1'b1; frame_len = 0; reloaded = 1'b1;
            end else if (i) begin
                // CRC-INIT: reload wins over a byte at the same edge
                if (v) c_init_valid = c_init_valid + 1;
                if (m_known && frame_len > 0) c_init_mid = c_init_mid + 1;
                m_run = 8'hFF; m_known = 1'b1; frame_len = 0; reloaded = 1'b1;
            end else if (v) begin
                // CRC-POLY / CRC-ORDER
                if (m_known) begin
                    m_run = spec_take_byte(m_run, d);
                    frame_len = frame_len + 1;
                    c_bytes = c_bytes + 1;
                    if (frame_len == 16) c_long = c_long + 1;
                    if (d == 8'h00 || d == 8'hFF || d == 8'h80 || d == 8'h01)
                        c_corner_data = c_corner_data + 1;
                end
            end else begin
                // CRC-HOLD
                if (m_known) c_hold = c_hold + 1;
            end

            #1;
            if (m_known) begin
                check("scoreboard after edge", m_run ^ 8'hFF);
                if (reloaded) begin
                    // CRC-EMPTY, stated directly from the spec
                    check("CRC-EMPTY after reload", 8'h00);
                    c_empty = c_empty + 1;
                end
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Constrained-random cycle. Probabilities in per-mille.
    // Constraints (spec 1, 2): any combination of rst_n/init/valid is
    // legal at any edge; data is any byte. Data is biased toward the
    // boundary bytes 0x00, 0xFF, 0x80, 0x01.
    // ------------------------------------------------------------------
    task rand_cycle(input integer p_rst, input integer p_init, input integer p_valid);
        integer r1, r2, r3, r4, r5;
        reg rr, ii, vv;
        reg [7:0] d;
        begin
            r1 = {$random(seed)} % 1000;
            r2 = {$random(seed)} % 1000;
            r3 = {$random(seed)} % 1000;
            r4 = {$random(seed)} % 100;
            r5 = {$random(seed)} % 4;
            rr = (r1 < p_rst) ? 1'b0 : 1'b1;
            ii = (r2 < p_init) ? 1'b1 : 1'b0;
            vv = (r3 < p_valid) ? 1'b1 : 1'b0;
            if (r4 < 25) begin
                case (r5)
                    0: d = 8'h00;
                    1: d = 8'hFF;
                    2: d = 8'h80;
                    default: d = 8'h01;
                endcase
            end else begin
                d = $random(seed);
            end
            step(rr, ii, vv, d);
        end
    endtask

    // ------------------------------------------------------------------
    // Verdict line, nonce printed byte by byte without padding.
    // ------------------------------------------------------------------
    task print_verdict;
        integer b;
        reg [7:0] ch;
        begin
            $write("NIRMAAN-SIM ");
            for (b = 255; b >= 0; b = b - 1) begin
                ch = nonce[b*8 +: 8];
                if (ch != 8'h00)
                    $write("%c", ch);
            end
            $display(" %0d passed, %0d failed", n_pass, n_fail);
        end
    endtask

    integer n;

    initial begin : main
        seed  = SEED;
        nonce = 0;
        have_nonce = 1'b0;
        if ($value$plusargs("nonce=%s", nonce))                  have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN_NONCE=%s", nonce))     have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce))     have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce)) have_nonce = 1'b1;
        $display("TB tb_crc8: seed = %0d (0x%h)", SEED, SEED);

        // ---------------- Directed scenarios (expected values from spec) ---
        step(1'b0, 1'b0, 1'b0, 8'h00);                 // reset
        step(1'b0, 1'b0, 1'b1, 8'hA5);                 // reset with a byte offered
        check("CRC-RESET/EMPTY reset beats valid", 8'h00);

        step(1'b1, 1'b0, 1'b1, 8'h00);
        check("CRC-POLY byte 0x00 -> 0x0C", 8'h0C);
        step(1'b1, 1'b0, 1'b0, 8'h3C);                 // valid low, data changes
        check("CRC-HOLD valid low", 8'h0C);
        step(1'b1, 1'b0, 1'b0, 8'hC3);
        check("CRC-HOLD valid low second cycle", 8'h0C);

        step(1'b1, 1'b1, 1'b0, 8'h00);
        check("CRC-INIT reload", 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'h01);
        check("CRC-ORDER byte 0x01 -> 0x0B", 8'h0B);

        step(1'b1, 1'b1, 1'b1, 8'h55);                 // init and valid together
        check("CRC-INIT wins over valid", 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'h80);
        check("CRC-ORDER byte 0x80 -> 0x85", 8'h85);

        step(1'b0, 1'b1, 1'b1, 8'h12);                 // reset mid-frame
        check("CRC-RESET mid-frame", 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'hFF);
        check("CRC-POLY byte 0xFF -> 0xFF", 8'hFF);

        step(1'b1, 1'b1, 1'b0, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'h00);
        check("CRC-POLY bytes 00,00 -> 0x28", 8'h28);

        // ---------------- Constrained-random phases -------------------------
        // Phase A: stress, frequent reloads and resets coinciding with bytes
        for (n = 0; n < 4000; n = n + 1) rand_cycle(30, 150, 700);
        // Phase B: typical traffic
        for (n = 0; n < 8000; n = n + 1) rand_cycle(5, 40, 750);
        // Phase C: long frames, rare reloads
        for (n = 0; n < 4000; n = n + 1) rand_cycle(1, 5, 900);

        // ---------------- Coverage goals: fail if a corner was missed -------
        require_count("bytes taken",                 c_bytes,       8000);
        require_count("hold cycles",                 c_hold,         500);
        require_count("init with valid same edge",   c_init_valid,    50);
        require_count("init mid-frame",              c_init_mid,      50);
        require_count("reset with valid",            c_rst_valid,     20);
        require_count("reset with init",             c_rst_init,      10);
        require_count("reset mid-frame",             c_rst_mid,       10);
        require_count("frames of >=16 bytes",        c_long,          20);
        require_count("boundary data bytes taken",   c_corner_data,  500);
        require_count("empty-frame checks",          c_empty,        200);

        if (!have_nonce) begin
            n_fail = n_fail + 1;
            $display("ERROR: run nonce plusarg not found");
        end

        $display("TB tb_crc8 done: seed=%0d bytes=%0d checks passed=%0d failed=%0d",
                 SEED, c_bytes, n_pass, n_fail);
        print_verdict;
        $finish;
    end
endmodule
=== END FILE ===
